def solid_squares(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and not seen[r][c]:
                v=g[r][c]; st=[(r,c)]; seen[r][c]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==v:
                            seen[x][y]=True; st.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                h,w=r1-r0+1,c1-c0+1
                if h==w and len(comp)==h*w:  # solid square
                    out.append(((r0+r1)//2,(c0+c1)//2,v))
    return out

def transform(g):
